package com.astarworks.astera.core.domain.hologram

/**
 * Opaque handle to a live hologram managed by
 * [com.astarworks.astera.core.application.port.outbound.IHologramGateway].
 *
 * Generated by the gateway on `spawn`, stable for the gateway impl's
 * lifetime, not portable across plugin restarts (holograms are ephemeral
 * by design in Wave 5h — persistent holograms land in a later phase).
 */
@JvmInline
public value class HologramHandle(public val value: String) {
    init {
        require(value.isNotBlank()) { "HologramHandle must not be blank" }
    }

    override fun toString(): String = value
}
